void swap_rows(MatrixF & A, msize_t row1, msize_t row2) {
	for (msize_t col = 0; col < A.cols(); col++) {
		float tmp = A(row1, col);
		A(row1, col) = A(row2, col);
		A(row2, col) = tmp;
	}
}

